#!/usr/bin/env python3
import os
import re
import subprocess
import requests
import sys
from time import sleep

# --- Helper Functions ---

def fetch_article_content(url):
    """Fetch article content using curl for reliability."""
    print(f"Fetching {url}...")
    result = subprocess.run(
        ["curl", "-s", "-L", url], # Added -L to follow redirects
        capture_output=True,
        text=True
    )
    html = result.stdout

    # Extract title (optional, for logging)
    title_match = re.search(r'<title>(.*?)</title>', html, re.IGNORECASE)
    if title_match:
        print(f"Title: {title_match.group(1)}")

    # Specific extraction for Paul Graham's site to avoid nav/footer noise
    # His essays are usually in a <font face="verdana"> tag inside a <td>
    # But for a generic approach based on the skill, I'll stick to a robust cleaning.
    # However, to be more precise:

    # Remove scripts and styles
    text = re.sub(r'<script[^>]*>.*?</script>', '', html, flags=re.DOTALL | re.IGNORECASE)
    text = re.sub(r'<style[^>]*>.*?</style>', '', text, flags=re.DOTALL | re.IGNORECASE)

    # Try to target the main content if possible. Paul Graham's site uses tables.
    # A simple heuristic is finding the longest block of text.

    # Strip tags
    text = re.sub(r'<[^>]+>', ' ', text)

    # Normalize whitespace
    text = re.sub(r'\s+', ' ', text).strip()

    # Post-processing to remove likely navigation bits (start and end)
    # This is a bit hacky but generic without BS4.
    # Paul Graham's essays usually start after the title image.

    return text

def verify_content(text, expected_min_chars=1000):
    if len(text) < expected_min_chars:
        print(f"WARNING: Content may be truncated ({len(text)} chars)")
        return False
    return True

def clean_text_for_tts(text):
    # Remove URLs
    text = re.sub(r'http[s]?://\S+', ' link ', text)
    # Remove footnote markers like [1]
    text = re.sub(r'\[\d+\]', '', text)
    # Normalize
    text = re.sub(r'\s+', ' ', text)
    # Remove some special chars but keep punctuation
    text = re.sub(r'[^\w\s.,!?;:\'"()-]', '', text)
    return text.strip()

def chunk_text(text, max_chars=4000):
    sentences = re.split(r'(?<=[.!?])\s+', text)
    chunks = []
    current_chunk = ""
    for sentence in sentences:
        if len(current_chunk) + len(sentence) < max_chars:
            current_chunk += sentence + " "
        else:
            if current_chunk:
                chunks.append(current_chunk.strip())
            current_chunk = sentence + " "
    if current_chunk:
        chunks.append(current_chunk.strip())
    return chunks

# --- TTS Providers ---

def create_with_elevenlabs(text, output_path):
    api_key = os.environ.get("ELEVENLABS_API_KEY")
    # Default voice (Rachel)
    voice_id = "21m00Tcm4TlvDq8ikWAM" 

    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    print(f"Converting {len(chunks)} chunks with ElevenLabs...")

    for i, chunk in enumerate(chunks):
        chunk_file = f"/root/.gemini/tmp/chunk_{i:03d}.mp3"

        try:
            response = requests.post(
                f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}",
                headers={
                    "xi-api-key": api_key,
                    "Content-Type": "application/json"
                },
                json={
                    "text": chunk,
                    "model_id": "eleven_monolingual_v1",
                    "voice_settings": {"stability": 0.5, "similarity_boost": 0.75}
                }
            )

            if response.status_code == 200:
                with open(chunk_file, "wb") as f:
                    f.write(response.content)
                audio_files.append(chunk_file)
            else:
                print(f"Error chunk {i}: {response.status_code} - {response.text}")
                return False
        except Exception as e:
            print(f"Exception for chunk {i}: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

def create_with_openai(text, output_path):
    api_key = os.environ.get("OPENAI_API_KEY")
    chunks = chunk_text(text, max_chars=4000)
    audio_files = []

    print(f"Converting {len(chunks)} chunks with OpenAI...")

    for i, chunk in enumerate(chunks):
        chunk_file = f"/root/.gemini/tmp/chunk_{i:03d}.mp3"

        try:
            response = requests.post(
                "https://api.openai.com/v1/audio/speech",
                headers={
                    "Authorization": f"Bearer {api_key}",
                    "Content-Type": "application/json"
                },
                json={
                    "model": "tts-1",
                    "input": chunk,
                    "voice": "onyx",
                    "response_format": "mp3"
                }
            )

            if response.status_code == 200:
                with open(chunk_file, "wb") as f:
                    f.write(response.content)
                audio_files.append(chunk_file)
            else:
                print(f"Error chunk {i}: {response.status_code} - {response.text}")
                return False
        except Exception as e:
            print(f"Exception for chunk {i}: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

def create_with_gtts(text, output_path):
    print("Using gTTS fallback...")
    try:
        from gtts import gTTS
    except ImportError:
        print("Installing gTTS...")
        subprocess.run([sys.executable, "-m", "pip", "install", "gTTS"], check=True)
        from gtts import gTTS

    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/root/.gemini/tmp/chunk_{i:03d}.mp3"
        print(f"Processing chunk {i+1}/{len(chunks)}...")
        try:
            tts = gTTS(text=chunk, lang='en', slow=False)
            tts.save(chunk_file)
            audio_files.append(chunk_file)
        except Exception as e:
            print(f"Error gTTS chunk {i}: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

def concatenate_audio(audio_files, output_path):
    if not audio_files:
        return False

    list_file = "/root/.gemini/tmp/audio_list.txt"
    with open(list_file, "w") as f:
        for audio_file in audio_files:
            f.write(f"file '{audio_file}'\n")

    print("Concatenating audio files...")
    result = subprocess.run([
        "ffmpeg", "-y", "-f", "concat", "-safe", "0",
        "-i", list_file, "-c", "copy", output_path
    ], capture_output=True)

    if result.returncode != 0:
        print("FFmpeg Error:")
        print(result.stderr.decode())

    # Cleanup
    for f in audio_files:
        if os.path.exists(f):
            os.unlink(f)
    if os.path.exists(list_file):
        os.unlink(list_file)

    return result.returncode == 0

def main():
    # Ensure tmp dir exists
    os.makedirs("/root/.gemini/tmp", exist_ok=True)

    urls = [
        "http://paulgraham.com/ds.html",
        "https://paulgraham.com/foundermode.html"
    ]

    full_text = ""
    for url in urls:
        raw_text = fetch_article_content(url)
        if verify_content(raw_text):
            # Attempt to strip header/footer manually for PG sites
            # Usually starts with title and ends with footer
            # Rough split by "October 2023" or "September 2024" dates is risky
            # We'll rely on the clean_text_for_tts to remove garbage characters
            # and accept some navigation text might be included.

            # Simple PG specific cleanup: Remove the very bottom footer
            # "© mmxx pg" or "FAQ" links often at bottom
            if "FAQ" in raw_text[-500:]:
                raw_text = raw_text.rsplit("FAQ", 1)[0]

            full_text += f"\n\nNext Essay.\n\n{raw_text}"
        else:
            print(f"Skipping {url} due to content verification failure.")

    cleaned_text = clean_text_for_tts(full_text)
    print(f"Total text length: {len(cleaned_text)} chars")

    if not cleaned_text:
        print("No text to convert.")
        return

    output_path = "/root/audiobook.mp3"

    if os.environ.get("ELEVENLABS_API_KEY"):
        if not create_with_elevenlabs(cleaned_text, output_path):
            print("ElevenLabs failed, trying OpenAI...")
            if os.environ.get("OPENAI_API_KEY"):
                 create_with_openai(cleaned_text, output_path)
    elif os.environ.get("OPENAI_API_KEY"):
        create_with_openai(cleaned_text, output_path)
    else:
        create_with_gtts(cleaned_text, output_path)

if __name__ == "__main__":
    main()

